-- All fixtures are label-only and roll back; Production, Packaging SKUs and permissions remain read only.
do $$
declare
 actor uuid; readonly_actor uuid; p public.factory_productions; editor jsonb; payload jsonb; draft jsonb; bad jsonb;
 template public.factory_label_templates; base integer; request uuid:=gen_random_uuid(); publish_request uuid:=gen_random_uuid();
 v_template_key text:='qa-label-'||gen_random_uuid()::text; template_draft jsonb; version2 uuid; job uuid; device uuid:=gen_random_uuid(); claim uuid:=gen_random_uuid();
 candidate jsonb; frozen jsonb; raster jsonb; denied boolean; checks integer:=0; before_data text; after_data text;
begin
 select md5(jsonb_build_object('production',(select jsonb_agg(to_jsonb(x) order by id) from public.factory_productions x),'products',(select jsonb_agg(to_jsonb(x) order by id) from public.factory_finished_goods x))::text) into before_data;
 begin
  select e.auth_user_id into strict actor from public.employees e join public.roles r on r.id=e.role_id where r.name='owner' and lower(e.employment_status)='active' limit 1;
  perform set_config('request.jwt.claim.sub',actor::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
  select * into strict p from public.factory_productions where status='completed' and expiry_date is not null and manufacturing_date is not null and actual_pack_qty between 1 and 10000 order by created_at desc limit 1;
  select * into strict template from public.factory_label_templates where template_key='s08-sambal' order by version desc limit 1;
  editor:=public.factory_label_editor('product',p.finished_good_id::text);base:=coalesce((editor->'published'->>'version')::integer,0);
  payload:=jsonb_build_object('template_id',template.id,'width_mm',80,'height_mm',90,'net_weight','QA weight','storage_instructions','QA freezer','shelf_life_days',180,'expiry_rule','production','content',jsonb_build_object('product_name','QA label-only name','ingredients','QA ingredients'));
  draft:=public.factory_label_save_draft('product',p.finished_good_id::text,payload,coalesce((editor->'draft'->>'revision')::integer,0),base,request);
  assert draft->>'state'='draft','draft not persisted';checks:=checks+1;
  assert public.factory_label_save_draft('product',p.finished_good_id::text,payload,coalesce((editor->'draft'->>'revision')::integer,0),base,request)=draft,'draft retry differs';checks:=checks+1;
  assert coalesce((public.factory_label_editor('product',p.finished_good_id::text)->'published'->>'version')::int,0)=base,'draft changed approved label';checks:=checks+1;
  denied:=false;begin perform public.factory_label_save_draft('product',p.finished_good_id::text,payload||'{"net_weight":"changed"}',0,base,request);exception when others then denied:=true;end;assert denied,'changed draft request accepted';checks:=checks+1;
  denied:=false;begin perform public.factory_label_save_draft('product',p.finished_good_id::text,payload,0,base,gen_random_uuid());exception when others then denied:=true;end;assert denied,'stale draft revision accepted';checks:=checks+1;
  denied:=false;begin perform public.factory_label_publish((draft->>'id')::uuid,(draft->>'revision')::integer,publish_request,'QA review',false);exception when others then denied:=true;end;assert denied,'unapproved draft published';checks:=checks+1;
  denied:=false;begin perform public.factory_label_publish((draft->>'id')::uuid,0,publish_request,'QA review',true);exception when others then denied:=true;end;assert denied,'stale publication accepted';checks:=checks+1;
  bad:=public.factory_label_save_draft('product',p.finished_good_id::text,payload||jsonb_build_object('content',jsonb_build_object('manufacturing_date','2020-01-01')),(draft->>'revision')::integer,base,gen_random_uuid());
  denied:=false;begin perform public.factory_label_publish((bad->>'id')::uuid,(bad->>'revision')::integer,gen_random_uuid(),'QA rejection',true);exception when others then denied:=true;end;assert denied,'Production-owned date editable';checks:=checks+1;
  bad:=public.factory_label_save_draft('product',p.finished_good_id::text,payload||jsonb_build_object('content',jsonb_build_object('text_overrides',jsonb_build_object('12','Invented expiry'))),(bad->>'revision')::integer,base,gen_random_uuid());
  denied:=false;begin perform public.factory_label_publish((bad->>'id')::uuid,(bad->>'revision')::integer,gen_random_uuid(),'QA rejection',true);exception when others then denied:=true;end;assert denied,'dynamic element accepted static override';checks:=checks+1;
  draft:=public.factory_label_save_draft('product',p.finished_good_id::text,payload,(bad->>'revision')::integer,base,gen_random_uuid());
  draft:=public.factory_label_publish((draft->>'id')::uuid,(draft->>'revision')::integer,publish_request,'QA approved label content; rolled back',true);
  assert draft->>'state'='published','publication failed';checks:=checks+1;
  assert public.factory_label_publish((draft->>'id')::uuid,(draft->>'revision')::integer,publish_request,'QA approved label content; rolled back',true)=draft,'publish retry differs';checks:=checks+1;
  denied:=false;begin perform public.factory_label_publish((draft->>'id')::uuid,(draft->>'revision')::integer,publish_request,'Different approval reason',true);exception when others then denied:=true;end;assert denied,'changed approval reused publication request';checks:=checks+1;
  candidate:=public.factory_label_candidate(p.id);assert candidate->>'product_name'='QA label-only name','approved SKU label content ignored';checks:=checks+1;
  assert (candidate->>'manufacturing_date')::date=p.manufacturing_date and (candidate->>'expiry_date')::date=p.expiry_date and (candidate->>'packaged_units')::numeric=p.actual_pack_qty,'label content overwrote Production authority';checks:=checks+1;
  assert candidate->>'ingredients'='QA ingredients','SKU ingredients not projected';checks:=checks+1;
  template_draft:=public.factory_label_save_draft('template',v_template_key,jsonb_build_object('name','QA reusable template','width_mm',80,'height_mm',90,'definition',template.definition),0,0,gen_random_uuid());
  template_draft:=public.factory_label_publish((template_draft->>'id')::uuid,1,gen_random_uuid(),'QA template approval; rolled back',true);
  version2:=(template_draft->>'published_id')::uuid;
  assert (select version=1 from public.factory_label_templates where id=version2),'first template version wrong';checks:=checks+1;
  template_draft:=public.factory_label_save_draft('template',v_template_key,jsonb_build_object('name','QA template second version','width_mm',80,'height_mm',90,'definition',template.definition),(template_draft->>'revision')::integer,1,gen_random_uuid());
  template_draft:=public.factory_label_publish((template_draft->>'id')::uuid,(template_draft->>'revision')::integer,gen_random_uuid(),'QA second template approval',true);
  assert (select count(*)=2 from public.factory_label_templates where factory_label_templates.template_key=v_template_key),'template versions overwritten';checks:=checks+1;
  assert public.factory_label_candidate(p.id)->>'template_id'=template.id::text,'shared template publication silently reassigned SKU';checks:=checks+1;
  draft:=public.factory_label_save_draft('product',p.finished_good_id::text,payload||jsonb_build_object('template_id',version2),(draft->>'revision')::integer,base+1,gen_random_uuid());
  assert exists(select 1 from jsonb_array_elements(public.factory_label_editor('product',p.finished_good_id::text)->'templates') t where t->>'id'=version2::text),'draft lost its pinned historical template';checks:=checks+1;
  perform public.factory_label_device(device,'QA Management bridge','No physical printer','spooler','Ready','[]');
  raster:=jsonb_build_object('format','mono1','width',639,'height',719,'data',encode(decode(repeat('00',80*719),'hex'),'base64'));
  job:=public.factory_label_enqueue(gen_random_uuid(),p.id,device,1,candidate,raster);frozen:=public.factory_label_candidate(p.id);
  draft:=public.factory_label_save_draft('product',p.finished_good_id::text,payload||jsonb_build_object('content',jsonb_build_object('product_name','Later approved name')),(draft->>'revision')::integer,base+1,gen_random_uuid());
  draft:=public.factory_label_publish((draft->>'id')::uuid,(draft->>'revision')::integer,gen_random_uuid(),'QA newer product content',true);
  assert public.factory_label_candidate(p.id)=frozen,'new approved version changed historical snapshot';checks:=checks+1;
  denied:=false;begin update public.factory_label_configs set content='{}' where id=(draft->>'published_id')::uuid;exception when others then denied:=true;end;assert denied,'approved content mutable';checks:=checks+1;
  perform public.factory_label_set_device_enabled(device,false,'QA pause bridge');
  denied:=false;begin perform public.factory_label_claim(device,claim);exception when insufficient_privilege then denied:=true;end;assert denied,'disabled bridge claimed job';checks:=checks+1;
  perform public.factory_label_set_device_enabled(device,true,'QA resume bridge');perform public.factory_label_claim(device,claim);
  denied:=false;begin perform public.factory_label_set_device_enabled(device,false,'QA disable during Printing');exception when others then denied:=true;end;assert denied,'active Printing bridge disabled';checks:=checks+1;
  perform public.factory_label_report(device,job,claim,'Sent','QA simulated submission');perform public.factory_label_resolve(job,'Confirmed','QA simulated inspection');
  assert (public.factory_label_management('products')->>'total')::integer=(select count(*) from public.factory_finished_goods),'Product Labels omitted SKUs';checks:=checks+1;
  assert (public.factory_label_management('printers',1,'QA Management')->>'total')::integer>=1,'bridge missing from management';checks:=checks+1;
  assert (select count(*)>=4 from public.factory_label_management_events where action='published'),'publication audit missing';checks:=checks+1;
  select e.auth_user_id into strict readonly_actor from public.employees e join public.roles r on r.id=e.role_id where r.name='factory_read_only_test' and lower(e.employment_status)='active' limit 1;
  perform set_config('request.jwt.claim.sub',readonly_actor::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',readonly_actor,'role','authenticated')::text,true);
  denied:=false;begin perform public.factory_label_save_draft('product',p.finished_good_id::text,payload,0,base,gen_random_uuid());exception when insufficient_privilege then denied:=true;end;assert denied,'read-only employee edited draft';checks:=checks+1;
  denied:=false;begin perform public.factory_label_publish((draft->>'id')::uuid,(draft->>'revision')::integer,gen_random_uuid(),'Unauthorized approve',true);exception when insufficient_privilege then denied:=true;end;assert denied,'read-only employee published';checks:=checks+1;
  denied:=false;begin perform public.factory_label_set_device_enabled(device,false,'Unauthorized device change');exception when insufficient_privilege then denied:=true;end;assert denied,'read-only employee changed device';checks:=checks+1;
  perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{}',true);
  denied:=false;begin perform public.factory_label_management();exception when insufficient_privilege then denied:=true;end;assert denied,'anonymous management read allowed';checks:=checks+1;
  assert not has_function_privilege('anon','public.factory_label_publish(uuid,integer,uuid,text,boolean)','EXECUTE'),'anonymous publish exposed';checks:=checks+1;
  assert not has_table_privilege('authenticated','public.factory_label_drafts','UPDATE'),'direct draft writes granted';checks:=checks+1;
  raise exception using errcode='FX001',message='Rollback label management fixtures';
 exception when sqlstate 'FX001' then null;
 end;
 select md5(jsonb_build_object('production',(select jsonb_agg(to_jsonb(x) order by id) from public.factory_productions x),'products',(select jsonb_agg(to_jsonb(x) order by id) from public.factory_finished_goods x))::text) into after_data;
 assert after_data=before_data,'Production or product master changed';
 perform set_config('feedx.label_management_qa',jsonb_build_object('checks',checks+1,'fixtures_rolled_back',true,'production_and_products_unchanged',true)::text,true);
end $$;
select current_setting('feedx.label_management_qa')::jsonb as label_management_qa;
